// ==== Parser da mensagem do WhatsApp (Evolution API) ====
const body = $input.first().json.body || $input.first().json;
const data = body?.data || {};
const key = data.key || {};

// ---- Texto da mensagem ----
const rawMessage = (
  data.message?.conversation ||
  data.message?.extendedTextMessage?.text ||
  ''
).trim();

// ---- Grupo vs 1:1 ----
const remoteJid = key.remoteJid || '';
const isGrupo = remoteJid.endsWith('@g.us');

// ---- Quem enviou (telefone real, tratando LID) ----
let jidRemetente = isGrupo
  ? (key.participantAlt || key.participant || '')
  : (key.participantAlt || remoteJid || '');
const isLid = jidRemetente.endsWith('@lid');
let from = jidRemetente.split('@')[0].replace(/\D/g, '');
if (!isLid && from.length === 12 && from.startsWith('55')) {
  from = from.slice(0, 4) + '9' + from.slice(4);
}

// ---- Onde responder ----
const respostaJid = remoteJid;

// ---- Mensagem citada (quote) ----
const ctx = data.contextInfo || data.message?.extendedTextMessage?.contextInfo || null;
const quoted = ctx?.quotedMessage || null;
let textoCitado = '';
if (quoted) {
  textoCitado = (
    quoted.conversation ||
    quoted.extendedTextMessage?.text ||
    quoted.imageMessage?.caption ||
    quoted.videoMessage?.caption ||
    ''
  ).trim();
}

// ---- Detecta comando ----
const parts = rawMessage.split(/\s+/);
const first = parts[0] || '';
const command = first.startsWith('/') ? first.toLowerCase() : '';

// Tudo depois do comando
const resto = rawMessage.slice(first.length).trim();

// Separa as tags (#chave:valor) do título
const tags = {};
const tagRegex = /#(\w+):(\S+)/g;
let m;
while ((m = tagRegex.exec(resto)) !== null) {
  tags[m[1].toLowerCase()] = m[2];
}

// Título = o resto SEM as tags
let titleDigitado = resto.replace(/#\w+:\S+/g, '').trim();

// ---- Regra do quote ----
// Se for /task, não há título digitado (só tags ou nada), e existe quote,
// usa o texto citado como título.
let title = titleDigitado;
if (command === '/task' && !titleDigitado && textoCitado) {
  title = textoCitado;
}

return [{
  json: {
    from,
    raw_message: rawMessage,
    command,
    title,
    tags,                        // { org: 'Eleva', area: 'Plataforma' }
    org: tags.org || '',
    area: tags.area || '',
    texto_citado: textoCitado,
    usou_quote: command === '/task' && !titleDigitado && !!textoCitado,
    resposta_jid: respostaJid,
    is_grupo: isGrupo,
    pusher_name: data.pushName || '',
    is_command: !!command
  }
}];

const resp = $input.first().json;
const parse = $('Parse do comando').first().json;

const AJUDA =
  '📋 *Comandos disponíveis:*\n\n' +
  '• /task Descrição #area:Marketing — cria uma tarefa\n' +
  '• /hoje — suas tarefas de hoje\n' +
  '• /done <id> — concluir tarefa\n' +
  '• /ajuda — mostra esta mensagem';

let mensagem;

// Se o comando foi /ajuda, responde a lista direto (não depende da função)
if (parse.command === '/ajuda') {
  mensagem = AJUDA;
} else if (resp && typeof resp.reply === 'string' && resp.reply.length > 0) {
  mensagem = resp.reply;
} else if (resp && resp.ok === false) {
  let motivo = resp.error || 'erro desconhecido';
  if (resp.details) {
    motivo += ' (campos: ' + Object.keys(resp.details).join(', ') + ')';
  }
  mensagem = '⚠️ Não consegui processar seu comando.\nMotivo: ' + motivo;
} else {
  mensagem = '⚠️ Ocorreu um erro inesperado. Tente novamente.';
}

return [{
  json: {
    mensagem_resposta: mensagem,
    from: parse.from
  }
}];

const p = $input.first().json;

let valido = true;
let erro = '';

// Lista dos únicos comandos que o bot responde
const comandosValidos = ['/task', '/hoje', '/done', '/ajuda'];

// ⛔ Não é comando (não começa com /) OU é um comando fora da lista → ignora TUDO
if (!p.is_command || !comandosValidos.includes(p.command)) {
  return [{ json: { ...p, valido: false, erro_validacao: '' } }];
}

// A partir daqui, é garantidamente um dos 4 comandos.

if (p.command === '/task') {
  if (!p.org) {
    valido = false;
    erro =
      '⚠️ Faltou a organização.\n\n' +
      'Use: /task Descrição #org:NomeDaOrg #area:NomeDaArea\n' +
      'Exemplo: /task Corrigir bug #org:Eleva #area:Plataforma';
  } else if (!p.title) {
    valido = false;
    erro =
      '⚠️ Faltou a descrição da tarefa.\n\n' +
      'Digite o texto após /task, ou responda a uma mensagem com /task.';
  }
} else if (p.command === '/done') {
  const codigo = (p.title || '').trim().split(/\s+/)[0] || '';
  if (!codigo) {
    valido = false;
    erro =
      '⚠️ Faltou o código da tarefa.\n\n' +
      'Use: /done <código>\nExemplo: /done 0232\nVeja os códigos com /hoje.';
  }
}

return [{
  json: { ...p, valido, erro_validacao: erro }
}];

