const helpers = this.helpers;
const nowSec  = Math.floor(Date.now() / 1000);

// ===================== CONFIG =====================
const N8N_HEALTH_URL    = 'https://webhook.miabuilder.com/healthz'; // CONFIRME. '' para pular.
const AWS_ONLY_REGIONS  = ['us-east-1'];   // [] = todas
const AWS_SERVICES      = [];              // [] = todos
const AWS_WINDOW_HOURS   = 72;
const META_RSS          = 'https://metastatus.com/outage-events-feed-whatsapp-business-api.rss';
const META_WINDOW_HOURS = 48;
const TASKS_HEALTH_URL  = 'https://tyreqzwkazvdkfqipkme.supabase.co/functions/v1/healthz'; // seu projeto Lovable (Cloud). '' p/ pular.
const OPENAI_MODEL      = 'gpt-4o-mini';
// ==================================================

const clip  = (s, n = 220) => (s && s.length > n) ? s.slice(0, n - 1).trim() + '…' : (s || '');
const unesc = s => String(s||'').replace(/<!\[CDATA\[|\]\]>/g,'').replace(/&amp;/g,'&')
  .replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&#39;|&apos;/g,"'").trim();

const services = [];

// --- Statuspage.io ---
// --- Statuspage.io ---
async function statuspage(name, base) {
  try {
    const d = await helpers.httpRequest({
      url: base + '/api/v2/summary.json',
      json: true,
      timeout: 10000
    });

    const ind = (d.status && d.status.indicator) || 'unknown';

    // Regiões que você quer monitorar
    const REGION_REGEX = /\b(sa-east-\d+|us-east-\d+|us-west-\d+)\b/i;

    // Incidentes ativos apenas das regiões SA e US
    const incidents = (d.incidents || [])
      .filter(i => !['resolved', 'completed', 'postmortem'].includes(i.status))
      .filter(i => {
        const text = JSON.stringify(i);
        return REGION_REGEX.test(text);
      })
      .slice(0, 2)
      .map(i => ({
        impact: i.impact,
        name: i.name,
        status: i.status,
        update: clip(
          (i.incident_updates && i.incident_updates[0])
            ? i.incident_updates[0].body
            : ''
        ),
        link: i.shortlink || ''
      }));

    // Componentes afetados apenas das regiões SA e US
    const affected = (d.components || [])
      .filter(c => !c.group && c.status && c.status !== 'operational')
      .filter(c => {
        const text = JSON.stringify(c);
        return REGION_REGEX.test(text);
      })
      .map(c => ({
        name: c.name,
        status: c.status
      }))
      .slice(0, 6);

    const maintenance = (d.scheduled_maintenances || [])
      .filter(m => m.status === 'in_progress')
      .map(m => m.name)
      .slice(0, 1);

    // Estado padrão da StatusPage
    let state = {
      none: 'ok',
      minor: 'degraded',
      major: 'major',
      critical: 'down',
      maintenance: 'maintenance'
    }[ind] || 'unknown';

    // Se houver incidente relevante, ele prevalece
    if (incidents.length) {
      if (incidents.some(i => i.impact === 'critical')) {
        state = 'down';
      } else if (incidents.some(i => i.impact === 'major')) {
        state = 'major';
      } else {
        state = 'degraded';
      }
    }

    return {
      service: name,
      state,
      summary: (d.status && d.status.description) || '',
      incidents,
      affected,
      maintenance
    };

  } catch (e) {
    return {
      service: name,
      state: 'unknown',
      error: 'sem resposta'
    };
  }
}

