// --- AWS Health (UTF-16) ---
try {
  const rawResp = await helpers.httpRequest({ url:'https://health.aws.amazon.com/public/currentevents', timeout:12000, encoding:'arraybuffer', json:false });
  const b = Buffer.isBuffer(rawResp) ? rawResp : Buffer.from(rawResp);
  let txt;
  if (b.length >= 2 && b[0] === 0xFF && b[1] === 0xFE) txt = b.toString('utf16le');
  else if (b.length >= 2 && b[0] === 0xFE && b[1] === 0xFF) { const c = Buffer.from(b); c.swap16(); txt = c.toString('utf16le'); }
  else { let z=0; for (let k=1;k<Math.min(b.length,200);k+=2) if (b[k]===0) z++; txt = z>50 ? b.toString('utf16le') : b.toString('utf8'); }
  txt = txt.replace(/^﻿/, '');
  const events = JSON.parse(txt.slice(txt.indexOf('[')));
  const lastUpdate = ev => { let mx=parseInt(ev.date,10)||0; for (const l of (ev.event_log||[])){ const t=parseInt(l.timestamp,10)||0; if(t>mx) mx=t; } return mx; };
  const regionMatch  = ev => !AWS_ONLY_REGIONS.length || AWS_ONLY_REGIONS.some(r => (ev.arn||'').includes(r) || (ev.service||'').includes(r));
  const serviceMatch = ev => { if(!AWS_SERVICES.length) return true; const h=((ev.service||'')+' '+(ev.service_name||'')+' '+(ev.arn||'')).toLowerCase(); return AWS_SERVICES.some(s=>h.includes(s.toLowerCase())); };
  const cutoff = nowSec - AWS_WINDOW_HOURS*3600;
  const recent = (events||[]).filter(ev => lastUpdate(ev) >= cutoff && regionMatch(ev) && serviceMatch(ev));
  const scope = (AWS_SERVICES.length ? AWS_SERVICES.join('/') : 'todos os serviços') + (AWS_ONLY_REGIONS.length ? ' @ '+AWS_ONLY_REGIONS.join(',') : '');
  services.push({
    service:'AWS', scope,
    state: recent.length ? 'degraded' : 'ok',
    incidents: recent.slice(0,3).map(ev => ({
      name: ev.service_name || ev.service, region: ev.region_name || '',
      summary: ev.summary || '',
      update: clip((ev.event_log && ev.event_log.length) ? ev.event_log[ev.event_log.length-1].message : '')
    }))
  });
} catch (e) {
  services.push({ service:'AWS', state:'unknown', error:'sem resposta' });
}

// --- Meta / WhatsApp Business (RSS) ---
try {
  const xml = String(await helpers.httpRequest({ url: META_RSS, timeout:10000 }));
  const items = [...xml.matchAll(/<item>([\s\S]*?)<\/item>/g)].map(m => {
    const seg=m[1];
    const title=unesc((seg.match(/<title>([\s\S]*?)<\/title>/)||[])[1]);
    const date =unesc((seg.match(/<pubDate>([\s\S]*?)<\/pubDate>/)||[])[1]);
    const mt=title.match(/^\[([^\]]+)\]:\s*(.+)$/);
    return { prefix:mt?mt[1].trim():'', comp:mt?mt[2].trim():title, ts:Math.floor((Date.parse(date)||0)/1000) };
  });
  const cutoff = nowSec - META_WINDOW_HOURS*3600;
  const latest = {};
  for (const it of items){ if(it.ts && it.ts<cutoff) continue; if(!latest[it.comp] || it.ts>latest[it.comp].ts) latest[it.comp]=it; }
  const active = Object.values(latest).filter(x => !/resolv/i.test(x.prefix));
  let state = 'ok';
  if (active.length) state = active.some(x=>/high|major|outage/i.test(x.prefix)) ? 'major' : 'degraded';
  else if (Object.values(latest).some(x=>/resolv/i.test(x.prefix))) state = 'recovered';
  services.push({ service:'Meta (WhatsApp)', state, incidents: active.slice(0,4).map(x => ({ level:x.prefix, component:x.comp })) });
} catch (e) {
  services.push({ service:'Meta (WhatsApp)', state:'unknown', error:'sem resposta' });
}

